 "content": "def transform(grid):
    """Copy the distinctive panel stencil to every panel, colored by row key."""
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r, row in enumerate(grid) if row and len(set(row)) == 1 and row[0] != 0]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0]
    sep_color = grid[sep_rows[0]][0] if sep_rows else grid[0][sep_cols[0]]
    rb = [-1] + sep_rows + [h]
    cb = [-1] + sep_cols + [w]
    panels = []
    for pr in range(len(rb) - 1):
        r0, r1 = rb[pr] + 1, rb[pr + 1]
        for pc in range(len(cb) - 1):
            c0, c1 = cb[pc] + 1, cb[pc + 1]
            cells = [(r-r0, c-c0, grid[r][c])
                     for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] not in (0, sep_color)]
            panels.append((pr, pc, r0, r1, c0, c1, cells))
    # The stencil is the nonempty panel whose occupied-cell shape is not a 2x2 block.
    candidates = []
    for pr, pc, r0, r1, c0, c1, cells in panels:
        if not cells:
            continue
        coords = {(r, c) for r, c, _ in cells}
        rs = [r for r, _ in coords]
        cs = [c for _, c in coords]
        is_square = (len(coords) == 4 and max(rs)-min(rs) == 1 and max(cs)-min(cs) == 1
                     and len({(r, c) for r in range(min(rs), max(rs)+1)
                              for c in range(min(cs), max(cs)+1)} & coords) == 4)
        if not is_square:
            candidates.append((pr, pc, r0, r1, c0, c1, cells))
    if len(candidates) != 1:
        raise ValueError(f'Expected one distinctive stencil panel, found {len(candidates)}')
    _, _, _, _, _, _, stencil_cells = candidates[0]
    stencil = {(r, c) for r, c, _ in stencil_cells}
    out = [row[:] for row in grid]
    for pr in range(len(rb)-1):
        r0, r1 = rb[pr]+1, rb[pr+1]
        # Each panel row inherits the foreground color of its leftmost panel.
        c0, c1 = cb[0]+1, cb[1]
        row_colors = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1)
                      if grid[r][c] not in (0, sep_color)]
        if not row_colors:
            raise ValueError(f'No row key in panel row {pr}')
        color = row_colors[0]
        for pc in range(len(cb)-1):
            tr0, tr1 = rb[pr]+1, rb[pr+1]
            tc0, tc1 = cb[pc]+1, cb[pc+1]
            for r in range(tr0, tr1):
                for c in range(tc0, tc1):
                    out[r][c] = color if (r-tr0, c-tc0) in stencil else 0
    return out
